<?php declare( strict_types=1 ); namespace Inc\Services\Exam; use Inc\DTO\Exam\ExamAccessTokenDTO; use Inc\Repositories\WPDBRepositories\ExamAccessTokenRepository; class ExamAccessTokenService { private ExamAccessTokenRepository $repo; private const TOKEN_LENGTH = 64; public function __construct( ?ExamAccessTokenRepository $repo = null ) { $this->repo = $repo ?? new ExamAccessTokenRepository(); } public function generateInvitationToken( int $sourceId, int $issuerUserId, ?int $expiryDays = null ): string { $token = bin2hex( random_bytes( self::TOKEN_LENGTH / 2 ) ); $tokenHash = hash( 'sha256', $token ); $expiresAt = $expiryDays ? gmdate( 'Y-m-d H:i:s', time() + ( $expiryDays * 86400 ) ) : null; $this->repo->insert( [ 'purpose' => 'invitation', 'target_id' => $sourceId, 'token_hash' => $tokenHash, 'generation' => 1, 'expires_at' => $expiresAt, 'issuer_user_id' => $issuerUserId, 'created_at' => current_time( 'mysql', true ), ] ); return $token; } public function verifyToken( string $token ): ?ExamAccessTokenDTO { $tokenHash = hash( 'sha256', $token ); $dto = $this->repo->findByHash( $tokenHash ); if ( ! $dto ) { return null; } if ( $dto->revokedAt ) { return null; } if ( $dto->expiresAt && current_time( 'mysql', true ) > $dto->expiresAt ) { return null; } return $dto; } public function consumeToken( int $tokenId ): bool { return $this->repo->update( $tokenId, [ 'consumed_at' => current_time( 'mysql', true ), ] ); } public function revokeToken( int $tokenId ): bool { return $this->repo->update( $tokenId, [ 'revoked_at' => current_time( 'mysql', true ), ] ); } public function passToken( int $tokenId, int $passedByUserId ): bool { return $this->repo->update( $tokenId, [ 'passed_at' => current_time( 'mysql', true ), 'passed_by_user_id' => $passedByUserId, ] ); } }
